{
    public static partial class BossProfiles
    {
        public const string SkollSetId = "set.boss_skoll";
        public const string SkollRewardId = "boss_skoll.glacial_core";
        public const string SkollNativeContract = "cold-heal-only;exact-coroutine-DoHeal-scope;exclude-generated-at-OnDealDamage;preserve-native-crit-chain-and-heal-processors;bonus-after-native-processors-capped-H;bonus-enters-native-bank-once;success-native-owner-heal-event-only;owner-shared-heal-and-burst-CD;consume-next-target-before-prepare-native-radius;interval-only-native-curve-result;no-bank-write;one-native-shot-per-tick;count-only-created-native-projectiles;exact-core-owner-source-parent-victim-ref-and-monotonic-native-life-not-creationTime-alone;clear-owner-room-epoch-gem-life";
        public const string SkollEventOrder = "expire-owner-marks;release-existing-three-on-next-E1-or-E2;stage2-slash;stage3-arrow;stage6-four-rain-terminal-shield;part-counters";

        private static BossChannelDef SkollChannel(string id, int value, int cap, BossCoefficientKind kind = BossCoefficientKind.Damage)
            => new BossChannelDef(id, value * 1000, cap * 1000, kind);
        private static BossMoveProfile SkollProfile(string suffix, string ja, string en, string zh, BossChannelDef[] channels, params BossAction[] actions)
            => new BossMoveProfile("boss_skoll." + suffix, SkollSetId, new Txt(ja, en, zh), channels, actions);
        private static BossAction SkollArrow(BossEvent kind, string channel, int delay, int radius, int cooldown = 0)
            => new BossAction(kind, BossMechanism.Field, BossPayload.Damage, channel, anchor: BossAnchor.Cursor,
                cooldownMillis: cooldown, delayMillis: delay,lifetimeMillis:BossSkollBalance.ArrowLifetimeMillis,maxInstances:BossSkollBalance.ArrowMaxInstances, radiusMilli: radius,rangeMilli:BossSkollBalance.ArrowRangeMilli, element: BossElement.Cold);
        private static BossAction SkollArrowTicks(string channel, int delay, int radius)
            => new BossAction(BossEvent.Clock, BossMechanism.Field, BossPayload.Damage, channel, delayMillis: delay,lifetimeMillis:BossSkollBalance.TickLifetimeMillis,intervalMillis:BossSkollBalance.TickIntervalMillis,count:BossSkollBalance.TickCount,maxInstances:BossSkollBalance.TickMaxInstances, radiusMilli: radius,rangeMilli:BossSkollBalance.TickRangeMilli, element: BossElement.Cold);

        internal static BossMoveProfile[] CreateSkollMoves() => new[]
        {
            SkollProfile("weapon", "通常攻撃が命中したとき、自身から8m以内の敵の位置へ、0.25秒後に長さ4m×幅1mの氷刃を放ち、攻撃力・魔力の高い方の28%（上限84%）の冷気ダメージを与える。再発動まで5秒かかる。", "When your basic attack hits an enemy within 8m, release an ice blade at that enemy's position after 0.25 seconds. The blade is 4m long and 1m wide, and deals Cold damage equal to 28% of whichever is higher: your Attack or Ability Power (cap: 84%). Cooldown: 5 seconds.", "通常攻击命中8m以内的敌人时，0.25秒后向其位置释放长4m、宽1m的冰刃，造成相当于攻击力与法术强度中较高一方28%（上限84%）的冰伤害。冷却5秒。", new[] { SkollChannel("SkollBlade",BossSkollBalance.SkollBladeValue,BossSkollBalance.SkollBladeCap) },
                new BossAction(BossEvent.MainHit,BossMechanism.Field,BossPayload.Damage,"SkollBlade",BossShape.Line,BossAnchor.Hit,cooldownMillis:BossSkollBalance.WeaponA0CooldownMillis,delayMillis:BossSkollBalance.WeaponA0DelayMillis,rangeMilli:BossSkollBalance.WeaponA0RangeMilli,widthMilli:BossSkollBalance.WeaponA0WidthMilli,magnitudeMilli:BossSkollBalance.WeaponA0MagnitudeMilli,element:BossElement.Cold)),
            SkollProfile("armor", "ダメージを受けたとき、その地点へ0.40秒後に半径2mの氷刃を放ち、攻撃力・魔力の高い方の25%（上限75%）の冷気ダメージを与える。再発動まで7秒かかる。", "When you take damage, release an ice blade at that position after 0.40 seconds, dealing Cold damage equal to 25% of whichever is higher: your Attack or Ability Power (cap: 75%), in a 2m radius. Cooldown: 7 seconds.", "受到伤害时，0.40秒后向该位置释放冰刃，对半径2m范围造成相当于攻击力与法术强度中较高一方25%（上限75%）的冰伤害。冷却7秒。", new[] { SkollChannel("SkollCounter",BossSkollBalance.SkollCounterValue,BossSkollBalance.SkollCounterCap) },
                new BossAction(BossEvent.NativeDamageTaken,BossMechanism.Field,BossPayload.Damage,"SkollCounter",cooldownMillis:BossSkollBalance.ArmorA0CooldownMillis,delayMillis:BossSkollBalance.ArmorA0DelayMillis,radiusMilli:BossSkollBalance.ArmorA0RadiusMilli,element:BossElement.Cold)),
            SkollProfile("charm", "通常記憶または奥義記憶を使ったとき、8m以内の指定地点に氷の矢を放つ。0.45秒後に半径1.8mの範囲へ攻撃力・魔力の高い方の18%（上限54%）の冷気ダメージを与え、その後、氷の領域（持続1.5秒）を生成する。領域は0.5秒ごとに3回、各6%（上限18%）の冷気ダメージを与える。再発動まで8秒かかる。", "When you use a normal or ultimate memory, fire an ice arrow at a selected point within 8m. After 0.45 seconds, it deals Cold damage equal to 18% of whichever is higher: your Attack or Ability Power (cap: 54%), in a 1.8m radius. It then creates an icy field lasting 1.5 seconds that deals Cold damage 3 times, every 0.5 seconds, each equal to 6% of whichever is higher: your Attack or Ability Power (cap: 18%). Cooldown: 8 seconds.", "使用普通记忆或奥义记忆时，向8m以内的指定地点释放冰箭。0.45秒后对半径1.8m范围造成相当于攻击力与法术强度中较高一方18%（上限54%）的冰伤害，随后生成持续1.5秒的冰之领域。领域每0.5秒造成1次伤害，共3次，每次相当于攻击力与法术强度中较高一方的6%（上限18%），为冰伤害。冷却8秒。", new[] { SkollChannel("SkollArrow",BossSkollBalance.SkollArrowValue,BossSkollBalance.SkollArrowCap),SkollChannel("SkollArrowTick",BossSkollBalance.SkollArrowTickValue,BossSkollBalance.SkollArrowTickCap) },
                SkollArrow(BossEvent.MemoryUse,"SkollArrow",BossSkollBalance.CharmA0DelayMillis,BossSkollBalance.CharmA0RadiusMilli,BossSkollBalance.CharmA0CooldownMillis),SkollArrowTicks("SkollArrowTick",BossSkollBalance.CharmA1DelayMillis,BossSkollBalance.CharmA1RadiusMilli)),
            SkollProfile("head", "6秒以内に通常攻撃を3回命中させると、敵の位置を中心に横一列（間隔1.5m）の3か所へ、0.50秒後、0.75秒後、1.00秒後にそれぞれ半径0.9mの範囲に攻撃力・魔力の高い方の12%（上限36%）の冷気ダメージを与える。再発動まで8秒かかる。", "After 3 basic attack hits within 6 seconds, strike 3 points in a horizontal row centered on the enemy's position, spaced 1.5m apart. The strikes occur after 0.50, 0.75, and 1.00 seconds, respectively, each dealing Cold damage equal to 12% of whichever is higher: your Attack or Ability Power (cap: 36%), in a 0.9m radius. Cooldown: 8 seconds.", "6秒内通常攻击命中3次后，以敌人位置为中心，向横向排列、间隔1.5m的3个地点分别于0.50秒后、0.75秒后和1.00秒后发动攻击，对各处半径0.9m范围造成相当于攻击力与法术强度中较高一方12%（上限36%）的冰伤害。冷却8秒。", new[] { SkollChannel("SkollRow",BossSkollBalance.SkollRowValue,BossSkollBalance.SkollRowCap) },
                new BossAction(BossEvent.MainHit,BossMechanism.Field,BossPayload.Damage,"SkollRow",BossShape.Circle,BossAnchor.Hit,cooldownMillis:BossSkollBalance.HeadA0CooldownMillis,delayMillis:BossSkollBalance.HeadA0DelayMillis,intervalMillis:BossSkollBalance.HeadA0IntervalMillis,count:BossSkollBalance.HeadA0Count,maxInstances:BossSkollBalance.HeadA0MaxInstances,mainHits:BossSkollBalance.HeadA0MainHits,counterLifetimeMillis:BossSkollBalance.HeadA0CounterLifetimeMillis,radiusMilli:BossSkollBalance.HeadA0RadiusMilli,widthMilli:BossSkollBalance.HeadA0WidthMilli,element:BossElement.Cold)),
            SkollProfile("hands", "6秒以内に通常攻撃を4回命中させると、前方4m・角度60度の扇状の範囲に予告を出し、0.25秒後に攻撃力・魔力の高い方の30%（上限90%）の冷気ダメージを与えて、敵を1mノックバックさせる。ボスと行動妨害が効かない敵は動かない。再発動まで6秒かかる。", "After 4 basic attack hits within 6 seconds, mark a 60-degree cone extending 4m in front of you. After a 0.25-second warning, deal Cold damage equal to 30% of whichever is higher: your Attack or Ability Power (cap: 90%), and knock enemies back 1m. Bosses and enemies immune to crowd control are not moved. Cooldown: 6 seconds.", "6秒内通常攻击命中4次后，在前方4m、角度60度的扇形范围显示预警，0.25秒后造成相当于攻击力与法术强度中较高一方30%（上限90%）的冰伤害，并将敌人击退1m。首领和免疫控制的敌人不会被移动。冷却6秒。", new[] { SkollChannel("SkollFan",BossSkollBalance.SkollFanValue,BossSkollBalance.SkollFanCap) },
                new BossAction(BossEvent.MainHit,BossMechanism.Field,BossPayload.Push,"SkollFan",BossShape.Fan,cooldownMillis:BossSkollBalance.HandsA0CooldownMillis,delayMillis:BossSkollBalance.HandsA0DelayMillis,mainHits:BossSkollBalance.HandsA0MainHits,counterLifetimeMillis:BossSkollBalance.HandsA0CounterLifetimeMillis,rangeMilli:BossSkollBalance.HandsA0RangeMilli,angleMilli:BossSkollBalance.HandsA0AngleMilli,magnitudeMilli:BossSkollBalance.HandsA0MagnitudeMilli,element:BossElement.Cold)),
            SkollProfile("feet", "移動が終わったとき、自身に付き従う半径2mの氷旋風を1秒間発生させる。氷旋風は0.25秒ごとに4回、攻撃力・魔力の高い方の7%（上限21%）の冷気ダメージを与える。再発動まで5秒かかる。", "When you finish moving, create an icy whirlwind with a 2m radius that follows you for 1 second. It deals Cold damage 4 times, every 0.25 seconds, each equal to 7% of whichever is higher: your Attack or Ability Power (cap: 21%). Cooldown: 5 seconds.", "移动结束时，生成跟随自身的半径2m冰旋风，持续1秒。每0.25秒造成1次伤害，共4次，每次相当于攻击力与法术强度中较高一方的7%（上限21%），为冰伤害。冷却5秒。", new[] { SkollChannel("SkollWhirl",BossSkollBalance.SkollWhirlValue,BossSkollBalance.SkollWhirlCap) },
                new BossAction(BossEvent.MovementCompleted,BossMechanism.Field,BossPayload.Damage,"SkollWhirl",cooldownMillis:BossSkollBalance.FeetA0CooldownMillis,delayMillis:BossSkollBalance.FeetA0DelayMillis,lifetimeMillis:BossSkollBalance.FeetA0LifetimeMillis,intervalMillis:BossSkollBalance.FeetA0IntervalMillis,count:BossSkollBalance.FeetA0Count,maxInstances:BossSkollBalance.FeetA0MaxInstances,radiusMilli:BossSkollBalance.FeetA0RadiusMilli,followOwner:true,element:BossElement.Cold)),
            SkollProfile("stage2", "通常攻撃が命中するか、通常記憶または奥義記憶を使ったとき、氷印を1つ得る。氷印は最大3個で、最後に得てから6秒間続く。氷印が3個たまった状態で次に通常攻撃を命中させるか記憶を使うと、全て消費して、8m以内の対象地点（敵または指定地点）へ0.4秒後に長さ5m×幅1mの氷裂きを放ち、攻撃力・魔力の高い方の35%の冷気ダメージを与える。再発動まで4秒かかる。", "When your basic attack hits or you use a normal or ultimate memory, gain 1 ice mark, up to 3. Marks last 6 seconds from the most recent gain. With 3 marks, your next basic attack hit or memory use consumes them all. After 0.4 seconds, release an icy slash 5m long and 1m wide at the target point within 8m (an enemy's position or a selected point), dealing Cold damage equal to 35% of whichever is higher: your Attack or Ability Power. Cooldown: 4 seconds.", "通常攻击命中或使用普通记忆、奥义记忆时，获得1个冰印，最多3个，自最后一次获得后持续6秒。持有3个冰印时，下一次通常攻击命中或使用记忆会消耗全部冰印，0.4秒后向8m以内的目标地点（敌人位置或指定地点）释放长5m、宽1m的冰裂斩，造成相当于攻击力与法术强度中较高一方35%的冰伤害。冷却4秒。", new[] { SkollChannel("SkollSeal",BossSkollBalance.SkollSealValue,BossSkollBalance.SkollSealCap,BossCoefficientKind.Stat),SkollChannel("SkollRelease",BossSkollBalance.SkollReleaseValue,BossSkollBalance.SkollReleaseCap) },
                new BossAction(BossEvent.MainHit,BossMechanism.Ledger,BossPayload.Mark,"SkollSeal",lifetimeMillis:BossSkollBalance.Stage2A0LifetimeMillis,count:BossSkollBalance.Stage2A0Count,ledgerId:"SkollOwnerMarks",element:BossElement.Cold),
                new BossAction(BossEvent.MemoryUse,BossMechanism.Ledger,BossPayload.Mark,"SkollSeal",lifetimeMillis:BossSkollBalance.Stage2A1LifetimeMillis,count:BossSkollBalance.Stage2A1Count,ledgerId:"SkollOwnerMarks",element:BossElement.Cold),
                new BossAction(BossEvent.Clock,BossMechanism.Field,BossPayload.Damage,"SkollRelease",BossShape.Line,BossAnchor.Hit,cooldownMillis:BossSkollBalance.Stage2A2CooldownMillis,delayMillis:BossSkollBalance.Stage2A2DelayMillis,rangeMilli:BossSkollBalance.Stage2A2RangeMilli,widthMilli:BossSkollBalance.Stage2A2WidthMilli,magnitudeMilli:BossSkollBalance.Stage2A2MagnitudeMilli,element:BossElement.Cold)),
            SkollProfile("stage3", "2部位セット効果の攻撃地点へ、氷矢を追加で放つ。0.65秒後に半径2mの範囲へ攻撃力・魔力の高い方の15%の冷気ダメージを与え、その後、冷気の領域（持続1.5秒）を生成する。領域は0.5秒ごとに3回、各5%の冷気ダメージを与え、同時に存在できるのは1つまでである。", "Add an ice arrow at the 2-piece set effect's attack point. After 0.65 seconds, it deals Cold damage equal to 15% of whichever is higher: your Attack or Ability Power, in a 2m radius. It then creates a field lasting 1.5 seconds that deals Cold damage 3 times, every 0.5 seconds, each equal to 5% of whichever is higher: your Attack or Ability Power. Only 1 field can exist at a time.", "在2件套效果的攻击地点追加释放冰箭。0.65秒后对半径2m范围造成相当于攻击力与法术强度中较高一方15%的冰伤害，随后生成持续1.5秒的领域。领域每0.5秒造成1次伤害，共3次，每次相当于攻击力与法术强度中较高一方的5%，为冰伤害。同时最多存在1个领域。", new[] { SkollChannel("SkollSealArrow",BossSkollBalance.SkollSealArrowValue,BossSkollBalance.SkollSealArrowCap),SkollChannel("SkollSealTick",BossSkollBalance.SkollSealTickValue,BossSkollBalance.SkollSealTickCap) },
                SkollArrow(BossEvent.Clock,"SkollSealArrow",BossSkollBalance.Stage3A0DelayMillis,BossSkollBalance.Stage3A0RadiusMilli),SkollArrowTicks("SkollSealTick",BossSkollBalance.Stage3A1DelayMillis,BossSkollBalance.Stage3A1RadiusMilli)),
            SkollProfile("stage6", "2部位セット効果が発動したとき、対象地点を囲む半径2mの4か所へ氷雨を降らせる。0.6秒後、0.8秒後、1.0秒後、1.2秒後に、それぞれ半径1mの範囲へ攻撃力・魔力の高い方の22.5%（合計90%、上限100%）の冷気ダメージを与える。最後の氷雨が降る1.2秒後には、敵に命中したかどうかに関わらず、自身が攻撃力・魔力の高い方の38%（上限40%）の障壁を2秒間得る。障壁は重ならない。再発動まで10秒かかる。", "When the 2-piece set effect activates, rain ice onto 4 points arranged 2m around the target point. After 0.6, 0.8, 1.0, and 1.2 seconds, respectively, each strike deals Cold damage equal to 22.5% of whichever is higher: your Attack or Ability Power (90% total; cap: 100%), in a 1m radius. When the final strike occurs at 1.2 seconds, gain a non-stacking shield equal to 38% of whichever is higher: your Attack or Ability Power (cap: 40%), for 2 seconds, whether or not an enemy was hit. Cooldown: 10 seconds.", "2件套效果发动时，在目标地点周围2m处排列的4个地点降下冰雨，分别于0.6秒后、0.8秒后、1.0秒后和1.2秒后，对各处半径1m范围造成相当于攻击力与法术强度中较高一方22.5%的冰伤害（合计90%，上限100%）。最后一波冰雨在1.2秒后落下时，无论是否命中敌人，均获得相当于攻击力与法术强度中较高一方38%（上限40%）的护盾，持续2秒。护盾不叠加。冷却10秒。", new[] { SkollChannel("SkollRain",BossSkollBalance.SkollRainValue,BossSkollBalance.SkollRainCap),SkollChannel("SkollRainShield",BossSkollBalance.SkollRainShieldValue,BossSkollBalance.SkollRainShieldCap,BossCoefficientKind.Shield) },
                new BossAction(BossEvent.Clock,BossMechanism.Field,BossPayload.Damage,"SkollRain",cooldownMillis:BossSkollBalance.Stage6A0CooldownMillis,delayMillis:BossSkollBalance.Stage6A0DelayMillis,intervalMillis:BossSkollBalance.Stage6A0IntervalMillis,count:BossSkollBalance.Stage6A0Count,maxInstances:BossSkollBalance.Stage6A0MaxInstances,radiusMilli:BossSkollBalance.Stage6A0RadiusMilli,rangeMilli:BossSkollBalance.Stage6A0RangeMilli,element:BossElement.Cold),
                new BossAction(BossEvent.Clock,BossMechanism.Defense,BossPayload.Shield,"SkollRainShield",delayMillis:BossSkollBalance.Stage6A1DelayMillis,lifetimeMillis:BossSkollBalance.Stage6A1LifetimeMillis,maxInstances:BossSkollBalance.Stage6A1MaxInstances,element:BossElement.Cold)),
        };

        internal static BossRewardProfile[] CreateSkollRewards()
        {
            BossRewardAction Heal() => new BossRewardAction(BossRewardActionKind.NativeHeal,BossSkollBalance.RewardHealValueMilli,BossSkollBalance.RewardHealCapMilli,cooldownMillis:BossSkollBalance.RewardHealCooldownMillis,order:0,magnitudeMilli:BossSkollBalance.RewardHealMagnitudeMilli);
            BossRewardAction Target() => new BossRewardAction(BossRewardActionKind.NativeTarget,durationMillis:BossSkollBalance.RewardTargetDurationMillis,order:1);
            return new[] { new BossRewardProfile(SkollRewardId,SkollSetId,"Gem_U_GlacialCore",BossRewardAdapter.GlacialCore,new[]
            {
                new BossRewardStage(1,new Txt("装備している核による冷気属性の回復効果だけが20%増える。増える量は攻撃力・魔力の高い方の12%までで、再発動まで2秒かかる。", "Increase only the Cold healing provided by your equipped core by 20%. The added healing is capped at 12% of whichever is higher: your Attack or Ability Power. Cooldown: 2 seconds.", "仅使装备的核心所提供的冰属性治疗效果提高20%。追加治疗量上限为攻击力与法术强度中较高一方的12%。冷却2秒。"),new[] { Heal() }),
                new BossRewardStage(2,new Txt("固有報酬の段階1の効果に加え、冷気回復のきっかけになった敵を2秒間記録する。装備している雪嶺の核が放つ次の弾丸は、その敵が射程内にいれば優先して狙う。変わるのは核の弾丸であり、プレイヤー本体の射撃ではない。", "In addition to boss reward stage 1, remember the enemy that triggered the Cold healing for 2 seconds. The next projectile fired by your equipped Snowcrest Core prioritizes that enemy if it is within range. This affects the core's projectile, not your own shooting.", "除首领专属奖励阶段1的效果外，记录触发冰治疗的敌人，持续2秒。装备的雪岭之核发射的下一枚弹体会优先瞄准该敌人，前提是其位于射程以内。仅影响核心的弹体，不影响自身射击。"),new[] { Heal(),Target() }),
                new BossRewardStage(3,new Txt("固有報酬の段階2の効果に加え、冷気回復の後1秒間、装備している雪嶺の核が蓄積ダメージを消費して放つ弾丸（最大3発）の発射間隔が、最短0.10秒まで短くなる。プレイヤー本体の攻撃速度は変わらず、蓄積がないときや射程内に敵がいないときは速くならない。再発動まで8秒かかる。", "In addition to boss reward stage 2, for 1 second after Cold healing, shorten the firing interval of up to 3 projectiles that your equipped Snowcrest Core fires by consuming stored damage, to as little as 0.10 seconds. This does not change your own attack speed, and does not accelerate firing without stored damage or an enemy within range. Cooldown: 8 seconds.", "除首领专属奖励阶段2的效果外，在冰治疗后1秒内，装备的雪岭之核通过消耗积存伤害发射的最多3枚弹体，其发射间隔缩短至最短0.10秒。自身攻击速度不变，没有积存伤害或射程内没有敌人时不会加快发射。冷却8秒。"),new[] { Heal(),Target(),new BossRewardAction(BossRewardActionKind.NativeInterval,cooldownMillis:BossSkollBalance.RewardIntervalCooldownMillis,durationMillis:BossSkollBalance.RewardIntervalDurationMillis,count:BossSkollBalance.RewardIntervalCount,order:2,intervalMillis:BossSkollBalance.RewardIntervalIntervalMillis) }),
            }) };
        }
        public static UniqueDef[] CreateSkollPieces() => new[]
        {
            new UniqueDef("set.boss_skoll.weapon","weapon.chain_sword",new Txt("氷雨の剣","Icerain Sword", "冰雨之剑"),SkollSetId,"boss_skoll.weapon"),
